mapper.select:
SELECT 
  FROM emp09_evaluation
  JOIN emp01_person ON emp09_person_id = emp01_person_id
 WHERE emp01_company_id = #{companyId}
   AND emp09_person_id  = #{personId}
 ORDER BY emp09_evaluation_dt DESC

mapper.update:
UPDATE emp09_evaluation
   SET emp09_evaluation_dt    = #{req.evaluationDt}::date
     , emp09_evaluation_org   = #{req.evaluationOrg}
     , emp09_evaluation_emp   = #{req.evaluationEmp}
     , emp09_evaluation_grade = #{req.evaluationGrade}
     , emp09_evaluation_desc  = #{req.evaluationDesc}
     , emp09_note             = #{req.note}
 WHERE emp09_evaluation_id = #{evaluationId}
   AND emp09_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )

mapper.delete:
DELETE FROM emp09_evaluation
 WHERE emp09_evaluation_id IN
#{id}
   AND emp09_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )
